# libdom (https://github.com/netsurf-browser/libdom, e4150b6 2026-11-15; MIT, src/COPYING):
# the sources its own build compiles (taken from a host build's list), with
# the files that build generates (gperf through ports/tools/gperf-lite.py),
# and the flags NetSurf's build system gives GCC (_ALIGNED, STMTEXPR) and NDEBUG, as its release builds
F="-std=c99 -D_BSD_SOURCE -D_DEFAULT_SOURCE -Dinline=__inline__ -D_ALIGNED=__attribute__((aligned)) -DSTMTEXPR=1 -DNDEBUG -Isrc/include -Isrc/src -Isrc -DWITH_HUBBUB_BINDING"
compile "$OBJ" "$F" src/bindings/hubbub/parser.c src/src/core/string.c src/src/core/node.c src/src/core/attr.c src/src/core/characterdata.c src/src/core/element.c src/src/core/implementation.c src/src/core/text.c src/src/core/typeinfo.c src/src/core/comment.c src/src/core/namednodemap.c src/src/core/nodelist.c src/src/core/cdatasection.c src/src/core/document_type.c src/src/core/entity_ref.c src/src/core/pi.c src/src/core/doc_fragment.c src/src/core/document.c src/src/core/tokenlist.c src/src/events/event.c src/src/events/dispatch.c src/src/events/event_target.c src/src/events/document_event.c src/src/events/custom_event.c src/src/events/keyboard_event.c src/src/events/mouse_wheel_event.c src/src/events/text_event.c src/src/events/event_listener.c src/src/events/mouse_event.c src/src/events/mutation_event.c src/src/events/ui_event.c src/src/events/mouse_multi_wheel_event.c src/src/events/mutation_name_event.c src/src/html/html_applet_element.c src/src/html/html_area_element.c src/src/html/html_anchor_element.c src/src/html/html_basefont_element.c src/src/html/html_base_element.c src/src/html/html_body_element.c src/src/html/html_button_element.c src/src/html/html_canvas_element.c src/src/html/html_collection.c src/src/html/html_document.c src/src/html/html_element.c src/src/html/html_dlist_element.c src/src/html/html_directory_element.c src/src/html/html_options_collection.c src/src/html/html_html_element.c src/src/html/html_head_element.c src/src/html/html_link_element.c src/src/html/html_title_element.c src/src/html/html_meta_element.c src/src/html/html_style_element.c src/src/html/html_form_element.c src/src/html/html_select_element.c src/src/html/html_input_element.c src/src/html/html_text_area_element.c src/src/html/html_opt_group_element.c src/src/html/html_option_element.c src/src/html/html_hr_element.c src/src/html/html_menu_element.c src/src/html/html_fieldset_element.c src/src/html/html_legend_element.c src/src/html/html_div_element.c src/src/html/html_par